package com.kuaixietech.coupler;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.kuaixietech.integration.*;
import com.kuaixietech.security.DomainAccessGuard;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.dao.DataRetrievalFailureException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.web.server.ResponseStatusException;
import static com.kuaixietech.coupler.CouplerModels.*;
class CouplerIsolationTest {
 final JdbcTemplate db=mock(JdbcTemplate.class);final DomainAccessGuard guard=mock(DomainAccessGuard.class);final IntegrationCipher cipher=new IntegrationCipher(Base64.getEncoder().encodeToString(new byte[32]));final CouplerAdapterRegistry adapters=mock(CouplerAdapterRegistry.class);final CouplerCatalog catalog=new CouplerCatalog(new ObjectMapper());
 final Map<String,String> environment=new HashMap<>();final Map<String,Map<String,Object>> scopes=new HashMap<>(),configs=new HashMap<>();final Map<String,Map<String,String>> versions=new HashMap<>();final List<String> writes=new ArrayList<>();Map<String,Object> runtime;
 CouplerService service(){when(guard.requireAdmin()).thenReturn("admin");when(db.queryForList(anyString(),any(Object[].class))).thenAnswer(c->query(c.getArgument(0),(Object[])c.getRawArguments()[1]));when(db.queryForList(anyString())).thenAnswer(c->query(c.getArgument(0),new Object[]{}));when(db.update(anyString(),any(Object[].class))).thenAnswer(c->update(c.getArgument(0),(Object[])c.getRawArguments()[1]));when(db.update(anyString())).thenAnswer(c->update(c.getArgument(0),new Object[]{}));return new CouplerService(db,guard,cipher,catalog,adapters,environment::get);}
 String key(Object...parts){return String.join("/",Arrays.stream(parts).map(String::valueOf).toList());}
 List<Map<String,Object>> one(Map<String,Object> row){return row==null?List.of():List.of(new LinkedHashMap<>(row));}
 List<Map<String,Object>> query(String sql,Object[] a){if(sql.startsWith("SELECT current_mode"))return one(runtime);if(sql.startsWith("SELECT selected_provider"))return one(scopes.get(key(a[0],a[1])));if(sql.startsWith("SELECT enabled,config_revision"))return one(configs.get(key(a[0],a[1],a[2])));if(sql.startsWith("SELECT field_key")){var result=new ArrayList<Map<String,Object>>();versions.getOrDefault(key(a),Map.of()).forEach((f,c)->result.add(Map.of("field_key",f,"field_cipher",c)));return result;}if(sql.startsWith("SELECT mode,category,selected_provider"))return scopes.values().stream().map(HashMap::new).map(r->(Map<String,Object>)r).toList();if(sql.startsWith("SELECT mode,category,provider,enabled"))return configs.values().stream().map(HashMap::new).map(r->(Map<String,Object>)r).toList();if(sql.startsWith("SELECT v.mode")){var result=new ArrayList<Map<String,Object>>();for(var config:configs.values()){var version=versions.getOrDefault(key(config.get("mode"),config.get("category"),config.get("provider"),config.get("config_revision")),Map.of());for(var item:version.entrySet()){var row=new HashMap<String,Object>(config);row.put("field_key",item.getKey());row.put("field_cipher",item.getValue());result.add(row);}}return result;}throw new AssertionError("unexpected read: "+sql);}
 int update(String sql,Object[] a){writes.add(sql);if(sql.startsWith("INSERT IGNORE INTO t_integration_runtime_state")){if(runtime==null){runtime=new HashMap<>();runtime.put("current_mode","SANDBOX");runtime.put("revision",0L);}return 1;}if(sql.startsWith("UPDATE t_integration_runtime_state")){runtime.put("current_mode",a[0]);runtime.put("revision",((Number)runtime.get("revision")).longValue()+1);return 1;}if(sql.startsWith("INSERT IGNORE INTO t_integration_mode_scopes")){scopes.computeIfAbsent(key(a[0],a[1]),k->{var row=new HashMap<String,Object>();row.put("mode",a[0]);row.put("category",a[1]);row.put("revision",0L);return row;});return 1;}if(sql.startsWith("INSERT IGNORE INTO t_integration_mode_configs")){configs.computeIfAbsent(key(a[0],a[1],a[2]),k->new HashMap<>(Map.of("mode",a[0],"category",a[1],"provider",a[2],"enabled",false,"config_revision",0L)));return 1;}if(sql.startsWith("INSERT INTO t_integration_config_values")){var map=versions.computeIfAbsent(key(a[0],a[1],a[2],a[3]),k->new HashMap<>());assertNull(map.put(a[4].toString(),a[5].toString()),"immutable version must not overwrite an existing field");return 1;}if(sql.startsWith("UPDATE t_integration_mode_configs")){var row=configs.get(key(a[3],a[4],a[5]));row.put("enabled",a[0]);row.put("config_revision",a[1]);return 1;}if(sql.startsWith("UPDATE t_integration_mode_scopes")){var row=scopes.get(key(a[2],a[3]));row.put("selected_provider",a[0]);row.put("revision",((Number)row.get("revision")).longValue()+1);return 1;}if(sql.startsWith("INSERT INTO t_admin_logs"))return 1;throw new AssertionError("unexpected mutation: "+sql);}
 Map<String,String> sms(String secret){return Map.of("access_key_id","id","access_key_secret",secret,"sign_name","Kuaixie","template_code","SMS_123","region","cn-hangzhou");}
 void saveSms(CouplerService s,String secret,long expected){s.save("SMS","aliyun",Mode.LIVE,new Save(sms(secret),List.of(),true,true,expected));}
 void enableSmsFeature(CouplerService s){s.save("FEATURES","flags",Mode.LIVE,new Save(Map.of("sms_enabled","true"),List.of(),true,true,0));}
 @Test void noStateDefaultsSandboxAndNeverBootstrapsDatabase(){var s=service();assertEquals(Mode.SANDBOX,s.current().mode());assertTrue(writes.isEmpty());assertThrows(ResponseStatusException.class,()->new CouplerModeGate(s).requireLiveNewCall("sms_dispatch"));assertTrue(writes.isEmpty());}
 @Test void schemaFailureNeverBecomesImplicitLive(){var s=service();when(db.queryForList(startsWith("SELECT current_mode"),any(Object[].class))).thenThrow(new DataRetrievalFailureException("missing table"));assertThrows(DataRetrievalFailureException.class,s::current);assertTrue(writes.isEmpty());}
 @Test void staleRuntimeSwitchDoesNotChangeMode(){var s=service();s.switchMode(new Switch(Mode.LIVE,0));assertThrows(ResponseStatusException.class,()->s.switchMode(new Switch(Mode.SANDBOX,0)));assertEquals(Mode.LIVE,s.current().mode());assertEquals(1,s.current().revision());}
 @Test void runtimeSwitchDoesNotCopySecretsOrModifyBusinessRecords(){var s=service();saveSms(s,"live-secret",0);var original=new HashMap<>(versions);s.switchMode(new Switch(Mode.SANDBOX,0));assertEquals(original,versions);assertTrue(writes.stream().noneMatch(sql->sql.contains("t_orders")||sql.contains("t_profiles")||sql.contains("t_currency_payments")));}
 @Test void saveUsesModeAndRevisionBoundAuthenticatedEncryption(){var s=service();saveSms(s,"live-secret",0);String stored=versions.get("LIVE/SMS/aliyun/1").get("access_key_secret");assertEquals("live-secret",cipher.open("coupler/LIVE/SMS/aliyun/1/access_key_secret",stored));assertThrows(IllegalStateException.class,()->cipher.open("coupler/SANDBOX/SMS/aliyun/1/access_key_secret",stored));assertThrows(IllegalStateException.class,()->cipher.open("coupler/LIVE/SMS/aliyun/2/access_key_secret",stored));assertFalse(stored.contains("live-secret"));}
 @Test void blankSecretRetentionAndExplicitClearAreSeparate(){var s=service();saveSms(s,"live-secret",0);s.save("SMS","aliyun",Mode.LIVE,new Save(Map.of("sign_name","new"),List.of(),true,true,1));assertEquals("live-secret",cipher.open("coupler/LIVE/SMS/aliyun/2/access_key_secret",versions.get("LIVE/SMS/aliyun/2").get("access_key_secret")));s.save("SMS","aliyun",Mode.LIVE,new Save(Map.of(),List.of("access_key_secret"),false,true,2));assertFalse(versions.get("LIVE/SMS/aliyun/3").containsKey("access_key_secret"));assertTrue(versions.get("LIVE/SMS/aliyun/1").containsKey("access_key_secret"));}
 @Test void scopeRevisionSerializesOtherProviderSelection(){var s=service();saveSms(s,"secret",0);assertThrows(ResponseStatusException.class,()->s.save("SMS","tencent",Mode.LIVE,new Save(Map.of(),List.of(),false,true,0)));assertEquals("aliyun",scopes.get("LIVE/SMS").get("selected_provider"));}
 @Test void selectedButDisabledNeverFallsBackToAnotherProvider(){var s=service();saveSms(s,"secret",0);s.save("SMS","aliyun",Mode.LIVE,new Save(Map.of(),List.of(),false,true,1));s.switchMode(new Switch(Mode.LIVE,0));assertTrue(s.legacyNewCall("aliyun","sms").managed());assertNull(s.legacyNewCall("aliyun","sms").values());assertNull(s.legacyNewCall("tencent","sms").values());}
 @Test void liveKeysAreNotUsedForSandboxCalls(){var s=service();saveSms(s,"secret",0);assertNull(s.legacyNewCall("aliyun","sms").values());assertThrows(IllegalStateException.class,()->s.resolve("SMS"));verify(adapters,never()).validate(any(),eq(Mode.SANDBOX),anyLong(),anyMap());}
 @Test void newCallsReceiveAnImmutableResolvedSnapshot(){var s=service();saveSms(s,"old-secret",0);enableSmsFeature(s);s.switchMode(new Switch(Mode.LIVE,0));var resolved=s.resolve("SMS");s.save("SMS","aliyun",Mode.LIVE,new Save(Map.of("access_key_secret","new-secret"),List.of(),true,true,1));assertEquals("old-secret",resolved.values().get("access_key_secret"));assertEquals(1,resolved.configRevision());assertThrows(UnsupportedOperationException.class,()->resolved.values().put("api_key","bad"));assertFalse(resolved.toString().contains("old-secret"));}
 @Test void existingLiveSnapshotsSurviveModeSwitchAndNewProviderSelection(){var s=service();saveSms(s,"original-live-key",0);s.switchMode(new Switch(Mode.LIVE,0));s.save("SMS","aliyun",Mode.LIVE,new Save(Map.of("access_key_secret","rotated-key"),List.of(),true,true,1));s.switchMode(new Switch(Mode.SANDBOX,1));var old=s.historicalLive("aliyun","sms",1);assertEquals("original-live-key",old.values().get("access_key_secret"));assertEquals("LIVE",old.values().get("_runtime_mode"));assertNull(s.legacyNewCall("aliyun","sms").values());}
 @Test void historicalMissingRevisionCannotFallBackToLegacyKeys(){var s=service();assertThrows(IllegalStateException.class,()->s.historicalLive("aliyun","sms",99));saveSms(s,"secret",0);assertThrows(IllegalStateException.class,()->s.historicalLive("aliyun","sms",99));}
 @Test void metadataNeverReturnsSecretsAndUsesFourBoundedReads(){var s=service();saveSms(s,"uniquely-hidden-secret",0);clearInvocations(db);var result=s.settings();assertFalse(result.toString().contains("uniquely-hidden-secret"));verify(db,times(3)).queryForList(anyString());verify(db,times(1)).queryForList(anyString(),any(Object[].class));}
 @Test void copiedCiphertextAcrossModesIsReportedUnreadable(){var s=service();saveSms(s,"secret",0);scopes.put("SANDBOX/SMS",new HashMap<>(Map.of("mode","SANDBOX","category","SMS","selected_provider","aliyun","revision",1L)));configs.put("SANDBOX/SMS/aliyun",new HashMap<>(Map.of("mode","SANDBOX","category","SMS","provider","aliyun","enabled",false,"config_revision",1L)));versions.put("SANDBOX/SMS/aliyun/1",new HashMap<>(versions.get("LIVE/SMS/aliyun/1")));var result=s.validate("SMS","aliyun",Mode.SANDBOX);assertFalse((Boolean)result.get("ready"));assertTrue(((List<?>)result.get("unreadableFields")).contains("access_key_secret"));}
 @Test void userCannotInjectReservedModeFields(){var s=service();assertThrows(IllegalArgumentException.class,()->s.save("SMS","aliyun",Mode.LIVE,new Save(Map.of("_runtime_mode","SANDBOX"),List.of(),false,true,0)));assertTrue(writes.isEmpty());}
 @Test void authorizationRunsBeforeAnyConfigurationReadOrWrite(){var s=service();when(guard.requireAdmin()).thenThrow(new SecurityException());assertThrows(SecurityException.class,s::settings);assertThrows(SecurityException.class,()->s.save("SMS","aliyun",Mode.LIVE,new Save(Map.of(),List.of(),false,false,0)));assertThrows(SecurityException.class,()->s.switchMode(new Switch(Mode.LIVE,0)));verifyNoInteractions(db);}
 @Test void sdkWithoutBusinessConsumerCannotBecomeCurrentChannel(){var s=service();var e=assertThrows(IllegalArgumentException.class,()->s.save("OSS","aws",Mode.LIVE,new Save(Map.of(),List.of(),false,true,0)));assertEquals("COUPLER_BUSINESS_CONSUMER_UNAVAILABLE",e.getMessage());assertTrue(writes.isEmpty());}

 @Test void environmentReferenceIsFrozenInEncryptedVersionAtExplicitSave(){var s=service();environment.put("COUPLER_TEST_SECRET","original-secret");saveSms(s,"env:COUPLER_TEST_SECRET",0);String encrypted=versions.get("LIVE/SMS/aliyun/1").get("access_key_secret");assertEquals("original-secret",cipher.open("coupler/LIVE/SMS/aliyun/1/access_key_secret",encrypted));environment.put("COUPLER_TEST_SECRET","rotated-secret");assertEquals("original-secret",s.historicalLive("aliyun","sms",1).values().get("access_key_secret"));s.save("SMS","aliyun",Mode.LIVE,new Save(Map.of("access_key_secret","env:COUPLER_TEST_SECRET"),List.of(),true,true,1));assertEquals("rotated-secret",s.historicalLive("aliyun","sms",2).values().get("access_key_secret"));assertEquals("original-secret",s.historicalLive("aliyun","sms",1).values().get("access_key_secret"));}
 @Test void missingEnvironmentReferenceCannotBePersistedEvenAsDisabledDraft(){var s=service();assertThrows(IllegalStateException.class,()->s.save("SMS","aliyun",Mode.LIVE,new Save(sms("env:COUPLER_TEST_MISSING"),List.of(),false,false,0)));assertTrue(versions.isEmpty());verifyNoInteractions(adapters);}
 @Test void historicalUnresolvedReferenceFailsClosedInsteadOfReadingNewEnvironment(){var s=service();saveSms(s,"old-secret",0);environment.put("COUPLER_TEST_SECRET","current-secret");versions.get("LIVE/SMS/aliyun/1").put("access_key_secret",cipher.seal("coupler/LIVE/SMS/aliyun/1/access_key_secret","env:COUPLER_TEST_SECRET"));var e=assertThrows(IllegalStateException.class,()->s.historicalLive("aliyun","sms",1));assertEquals("COUPLER_UNVERSIONED_ENV_REFERENCE_RESAVE_REQUIRED",e.getMessage());assertFalse((Boolean)s.validate("SMS","aliyun",Mode.LIVE).get("ready"));enableSmsFeature(s);s.switchMode(new Switch(Mode.LIVE,0));assertThrows(IllegalStateException.class,()->s.resolve("SMS"));}
 @Test void nestedEnvironmentReferenceCannotCreateUnversionedSnapshot(){var s=service();environment.put("COUPLER_TEST_SECRET","env:COUPLER_OTHER_SECRET");assertThrows(IllegalStateException.class,()->saveSms(s,"env:COUPLER_TEST_SECRET",0));assertTrue(versions.isEmpty());}

}
